// AgentConfig An agent's configuration (the draft, or a published version), with defaults applied.
type AgentConfig struct {
	// Audience Who may chat once published (a draft setting, versioned with publish)
	Audience    Audience            `json:"audience"`
	ChatModelId *openapi_types.UUID `json:"chatModelId"`

	// CitationMode none: no citations; snippet: title and snippet; snippet_link: also the URL of web pages
	CitationMode CitationMode `json:"citationMode"`

	// ContextTokenBudget Sources are trimmed to this many estimated tokens (characters / 4)
	ContextTokenBudget int `json:"contextTokenBudget"`

	// Filters Restricts retrieval by document metadata. Empty lists do not filter. sourceIds is intersected with the knowledge base's sources.
	Filters *MetadataFilter `json:"filters,omitempty"`

	// FollowUpSuggestions Suggest up to 3 follow-up questions under an answer with citations (docs/follow-ups.md); absent in configurations saved before v0.4.1 (on)
	FollowUpSuggestions *bool     `json:"followUpSuggestions,omitempty"`
	Instructions        string    `json:"instructions"`
	Kbs                 []AgentKB `json:"kbs"`
	MaxOutputTokens     *int      `json:"maxOutputTokens,omitempty"`

	// MaxTurns Tool mode: turns that may search
	MaxTurns int `json:"maxTurns"`

	// MinSimilarity Hits whose vector similarity (1 - cosine distance) is lower are dropped; 0 = off
	MinSimilarity float64 `json:"minSimilarity"`

	// Moderation An agent's moderation override. It can only make the audience's platform policy stricter: a rule's action and threshold combine with the platform's (the stronger action, the lower threshold), off keeps the platform's rule, and outputMode stream_checked or buffer applies where the platform's mode is less strict (stream_retract, then stream_checked, then buffer). The Phase 3 value "off" is still accepted as no override.
	Moderation AgentModeration `json:"moderation"`

	// QueryRewrite With history, rewrite the question as a query that stands on its own before retrieval
	QueryRewrite bool `json:"queryRewrite"`

	// ReasoningEffort How long the model thinks before answering. off turns thinking off in the way the model's compatibility setting thinkingOff says (nothing is sent when it has none); low, medium and high are sent as reasoning_effort when the model accepts it (supportsReasoningEffort). Absent: the audience's reasoning effort (the moderation policy's), else the model's default.
	ReasoningEffort *ReasoningEffort `json:"reasoningEffort,omitempty"`
	RefusalMessage  string           `json:"refusalMessage"`

	// Rerank Rerank searches with the platform's rerank model (when one is set); absent in configurations saved before v0.4 (on)
	Rerank *bool `json:"rerank,omitempty"`

	// RerankTopN Passages each reranked search keeps, for judging or the model
	RerankTopN       *int          `json:"rerankTopN,omitempty"`
	RetrievalMode    RetrievalMode `json:"retrievalMode"`
	StrictlyGrounded bool          `json:"strictlyGrounded"`

	// SystemOne The agent's "SystemOne checks" (Configure, Advanced). Absent or empty follows the platform. Only takes effect when a SystemOne model is configured; thresholds are platform-only.
	SystemOne   *AgentSystemOne `json:"systemOne,omitempty"`
	Temperature *float64        `json:"temperature,omitempty"`

	// Tools Approved MCP server tools the agent may call (docs/mcp-client.md), by ID; absent in configurations saved before v0.3
	Tools *[]openapi_types.UUID `json:"tools,omitempty"`
}

