// WebConfig A web source's normalised configuration (crawl-only settings are zero for scrape and batch)
type WebConfig struct {
	AllowSubdomains bool        `json:"allowSubdomains"`
	Exclude         []string    `json:"exclude"`
	IncludePrefixes []string    `json:"includePrefixes"`
	MaxDepth        int         `json:"maxDepth"`
	MaxPages        int         `json:"maxPages"`
	Mode            WebMode     `json:"mode"`
	Schedule        WebSchedule `json:"schedule"`

	// Tags Tags applied to every page of the source
	Tags        []string `json:"tags"`
	Urls        []string `json:"urls"`
	UseSitemaps bool     `json:"useSitemaps"`
}

// WebConfigInput A web source's configuration. URLs are normalised; every host must be on the crawl allowlist or approved for the team by a domain request (400 host_not_allowed). Unknown fields are rejected.
type WebConfigInput struct {
	// AllowSubdomains crawl only: also follow subdomains of the seed hosts (default false)
	AllowSubdomains *bool `json:"allowSubdomains,omitempty"`

	// Exclude crawl only: path patterns to skip, e.g. /calendar/** (* within a segment, ** across segments)
	Exclude *[]string `json:"exclude,omitempty"`

	// IncludePrefixes crawl only: path prefixes to follow, e.g. /admissions/ (empty = the whole host)
	IncludePrefixes *[]string `json:"includePrefixes,omitempty"`

	// MaxDepth crawl only: link hops from a seed (default 3)
	MaxDepth *int `json:"maxDepth,omitempty"`

	// MaxPages 1 to the platform's CRAWL_MAX_PAGES (default: 500 for crawl, the URL count for batch; always 1 for scrape)
	MaxPages *int         `json:"maxPages,omitempty"`
	Mode     WebMode      `json:"mode"`
	Schedule *WebSchedule `json:"schedule,omitempty"`

	// Tags Tags applied to every page (lower-cased, 1-64 characters, no commas); changing them retags existing pages
	Tags *[]string `json:"tags,omitempty"`

	// Urls scrape: exactly 1; batch: 1-1000; crawl: 1-20 seeds
	Urls []string `json:"urls"`

	// UseSitemaps crawl only: also seed from robots.txt/sitemap.xml (default true)
	UseSitemaps *bool `json:"useSitemaps,omitempty"`
}

